@Component({
  selector: 'app-tareas',
  templateUrl: './tareas.component.html',
})
export class TareasComponent implements OnInit, OnDestroy {
  @Input() equipoId!: string;
  tareas: Tarea[] = [];
  private destroy$ = new Subject<void>();

  constructor(private api: TareasApi) {}

  ngOnInit() {
    this.api.listar(this.equipoId).pipe(takeUntil(this.destroy$))
      .subscribe(t => (this.tareas = t));
  }

  ngOnDestroy() {
    this.destroy$.next();
  }
}

